#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

# Walks the repository owner through the human-only production steps of #194, #531, #534, #536, #539, #629, #118
# and #622 in one sitting. It only reads: GETs to production (the product's API with a read key held in memory)
# and gcloud and aws lists. Every write is the human's, in the browser, or printed for them to run. It checks each
# step live first, names the ticket when production answers 501 not-built, and records evidence in the git-ignored
# infra/wizards/production-pilot.evidence.md, refusing any section that holds a credential or an email address.
# Only the organisation and project slugs and the project ID go to infra/wizards/.env.

# Fixed, not read from the environment: an exported API_ORIGIN (a #79 §6 name) must not redirect the key.
PROJECT=skyclause
GCP_REGION=asia-southeast1
AWS_ACCOUNT=776566309118
SES_REGION=ap-southeast-2
SES_EVENTS_TOPIC_ARN=arn:aws:sns:ap-southeast-2:776566309118:skyclause-production-ses-events
MARKETING_ORIGIN=https://skyclause.m1ku.tech
APP_ORIGIN=https://app.skyclause.m1ku.tech
API_ORIGIN=https://api.skyclause.m1ku.tech
EVIDENCE_FILE="${EVIDENCE_FILE:-infra/wizards/production-pilot.evidence.md}"
SLUG_PATTERN='^[a-z0-9]+(-[a-z0-9]+)*$'
API_KEY_PATTERN='^skc_[A-Za-z0-9_-]{8,}$'

API_STATUS=""
API_BODY=""

# ask_valid ask|ask_secret KEY "Prompt" REGEX "Hint" asks until the answer matches REGEX, and stops
# the wizard if input ends.
ask_valid() {
  local read_with="$1" key="$2" prompt="$3" pattern="$4" hint="$5"
  while true; do
    "$read_with" "$key" "$prompt" || { warn "No input, so stopping."; exit 1; }
    [[ "${!key}" =~ $pattern ]] && return 0
    warn "$hint"
  done
}

# key_prefix KEY prints only the first 8 characters of an API key followed by an ellipsis.
key_prefix() {
  printf '%s…' "${1:0:8}"
}

# credentials_in names each kind of credential in stdin: the shapes packages/config/src/redact.ts scrubs from logs,
# plus signed-URL parameters. A call's ICS UID (call-…@ or night-…@skyclause.m1ku.tech) isn't an address. The
# 8-character key prefix is the longest key or bearer text that passes; a provider sk- key is far longer than a slug.
credentials_in() {
  python3 -c '
import re, sys
text = sys.stdin.read()
text = re.sub(r"(?<![A-Za-z0-9._%+-])(?:call|night)-[^\s@]+@skyclause\.m1ku\.tech\b", "", text)
kinds = [
    ("a private key", r"-----BEGIN [A-Z ]*PRIVATE KEY-----"),
    ("a signed-URL parameter", r"(?i)[?&](?:x-goog-signature|x-goog-credential|x-amz-signature|x-amz-credential|x-amz-security-token|googleaccessid|signature)="),
    ("a bearer token", r"(?i)\bbearer\s+[A-Za-z0-9._~+/=-]{9,}"),
    ("an API key", r"ya29\.[A-Za-z0-9._-]+|sk[cgw]_[A-Za-z0-9_-]{5,}|AIza[0-9A-Za-z_-]{35}|(?<![A-Za-z0-9])sk-[A-Za-z0-9_-]{32,}|\b(?:AKIA|ASIA)[0-9A-Z]{16}\b"),
    ("a subscriber link token", r"/subscribe/[A-Za-z0-9_-]{43}(?![A-Za-z0-9_-])"),
    ("an email address", r"[A-Za-z0-9._%+-]+@[A-Za-z0-9.-]+\.[A-Za-z]{2,}"),
]
print(" and ".join(kind for kind, pattern in kinds if re.search(pattern, text)))
'
}

init_evidence() {
  [[ -e "$EVIDENCE_FILE" ]] || (umask 077 && printf '# Production pilot verification evidence\n' > "$EVIDENCE_FILE")
}

# record_evidence ISSUE TITLE COMMAND OUTPUT appends one markdown section to EVIDENCE_FILE, or refuses the whole
# section, writing nothing, if it holds a credential or an email address.
record_evidence() {
  local issue="$1" title="$2" cmd="$3" out="$4" fence='```' section found
  section="$(printf '\n## %s — %s (%s)\n\n%sshell\n$ %s\n%s\n\n%stext\n%s\n%s' \
    "$issue" "$title" "$(date -u +%Y-%m-%dT%H:%M:%SZ)" "$fence" "$cmd" "$fence" "$fence" "$out" "$fence")"
  found="$(printf '%s' "$section" | credentials_in)" ||
    { warn "Couldn't check $issue evidence for credentials, so nothing was written."; return 1; }
  if [[ -n "$found" ]]; then
    warn "Refused to record $issue evidence: it holds $found. Nothing was written."
    SKIPPED+=("$issue $title: record it by hand, without $found")
    return 0
  fi
  init_evidence
  printf '%s\n' "$section" >> "$EVIDENCE_FILE"
  printf '  %s✓ recorded%s evidence for %s → %s\n' "$GREEN" "$RESET" "$issue" "$EVIDENCE_FILE"
}

# api_get PATH calls GET $API_ORIGIN$PATH with SKYCLAUSE_API_KEY passed over stdin, setting API_STATUS and API_BODY.
api_get() {
  local path="$1" raw
  raw="$(printf 'header = "Authorization: Bearer %s"\nheader = "Skyclause-Organization: %s"\nheader = "Accept: application/json"\n' \
    "$SKYCLAUSE_API_KEY" "$ORG_SLUG" | curl -sS -K - -w $'\n%{http_code}' "$API_ORIGIN$path")" || return 1
  API_STATUS="${raw##*$'\n'}"
  API_BODY="${raw%$'\n'*}"
}

# public_get URL calls GET URL with no credentials, setting API_STATUS and API_BODY.
public_get() {
  local raw
  raw="$(curl -sS -w $'\n%{http_code}' "$1")" || return 1
  API_STATUS="${raw##*$'\n'}"
  API_BODY="${raw%$'\n'*}"
}

# not_built OWNER succeeds when the last answer is the API's 501 not-built problem for OWNER (#79 §1): production
# says the operation has no handler yet. Any other answer, even a 501, is not that.
not_built() {
  [[ "$API_STATUS" == "501" ]] && printf '%s' "$API_BODY" | python3 -c '
import json, sys
body = json.load(sys.stdin)
sys.exit(0 if body.get("type", "").endswith("/problems/not-built") and body.get("owner") == sys.argv[1] else 1)
' "$1" 2>/dev/null
}

# json_field EXPR prints EXPR evaluated over API_BODY's JSON as data. An answer it can't read fails with a warning
# on stderr, which stops the wizard wherever the result is assigned.
json_field() {
  local expr="$1"
  printf '%s' "$API_BODY" | python3 -c "import json, sys; data = json.load(sys.stdin); print($expr)" 2>/dev/null ||
    { warn "Couldn't read $expr from the answer: $API_BODY" >&2; return 1; }
}

# revoke_snippet prints the DevTools line that revokes every API key named production-pilot in ORG_SLUG.
revoke_snippet() {
  printf "fetch('/api/orgs/%s/api-keys?limit=200').then(r=>r.json()).then(d=>Promise.all(d.data.filter(k=>k.name==='production-pilot').map(k=>fetch('/api/orgs/%s/api-keys/'+k.id,{method:'DELETE'}).then(r=>console.log('revoked',k.id,r.status)))))" \
    "$ORG_SLUG" "$ORG_SLUG"
}

# on_exit names the stage a run stopped in, so no early exit is silent, and says how to revoke a key it was given.
on_exit() {
  local status=$?
  (( status == 0 )) && return
  warn "Stopped in stage $_STAGE_INDEX/$TOTAL_STAGES (exit $status): the message above says why."
  if [[ -n "${SKYCLAUSE_API_KEY:-}" ]]; then
    note "Revoke this run's API key in the DevTools console on $APP_ORIGIN/$ORG_SLUG/settings/api-keys"
    note "(it expires 1 day after you made it anyway):"
    note "  $(revoke_snippet)"
  fi
}

run_wizard() {

TOTAL_STAGES=13
# An exported SKYCLAUSE_API_KEY (the CLI reads one) would carry the pasted key into every child's environment.
unset SKYCLAUSE_API_KEY
trap on_exit EXIT
cd "$(dirname "${BASH_SOURCE[0]}")/../.."
# Not the root .env, which Bun loads in local development.
[[ "$ENV_FILE" == .env ]] && ENV_FILE=infra/wizards/.env

banner "Production pilot checks and human steps (#194, #531, #534, #536, #539, #629, #118, #622)"

stage "Check tools, hosts and on-call contacts (#118, #629)"
for tool in curl python3 gcloud aws; do
  command -v "$tool" >/dev/null 2>&1 || { warn "$tool is missing: install it and re-run"; exit 1; }
done
for origin in "$MARKETING_ORIGIN" "$APP_ORIGIN" "$API_ORIGIN"; do
  if ! curl -fsS "$origin/health" >/dev/null; then
    warn "$origin/health did not answer 200; check production before continuing."
    exit 1
  fi
done
say "Production hosts ($MARKETING_ORIGIN, $APP_ORIGIN, $API_ORIGIN) answer /health with 200."
say "Checking ONCALL_CONTACTS in Secret Manager ($PROJECT) for #118 and #629..."
if ! oncall_list="$(gcloud secrets versions list ONCALL_CONTACTS --project="$PROJECT" --filter=state=ENABLED \
  --format='table(name,state,createTime)')"; then
  warn "gcloud couldn't list ONCALL_CONTACTS's versions in $PROJECT: its error is above."
  warn "Sign in as a project owner with 'gcloud auth login' and re-run."
  exit 1
fi
if [[ -z "$oncall_list" ]]; then
  warn "ONCALL_CONTACTS has no enabled version yet (#118, #629)."
  note "Run ./infra/wizards/oncall-contacts.sh yourself (about 10 minutes): it stores the contacts, and a second"
  note "run after oncall_contacts_ready is applied verifies the SMS numbers. Then re-run this wizard."
  SKIPPED+=("#118 / #629 store ONCALL_CONTACTS with ./infra/wizards/oncall-contacts.sh, then re-run")
else
  record_evidence "#118 / #629" "ONCALL_CONTACTS has an enabled version (listed by name, never accessed; the channels and a test page are still to check)" \
    "gcloud secrets versions list ONCALL_CONTACTS --project=$PROJECT --filter=state=ENABLED --format='table(name,state,createTime)'" \
    "$oncall_list"
  SKIPPED+=("#629 check the on-call notification channels exist and a test incident pages within 5 minutes, by hand")
fi
pause

stage "Check #622's deploy criteria that still wait"
# The docs host answers 200 on every path with or without a docs build, so its status proves nothing.
note "#622's docs criterion comes after #210 gives apps/docs a build; then check the deployed web image by hand."
SKIPPED+=("#622 the web image contains the docs export: after #210 gives apps/docs a build, check the deployed image by hand")
say "Checking Cloud Run for the commons-provision job (#622)..."
if ! commons_job="$(gcloud run jobs list --region="$GCP_REGION" --project="$PROJECT" \
  --filter=metadata.name=commons-provision --format='value(metadata.name)')"; then
  warn "Couldn't list Cloud Run jobs in $PROJECT: gcloud's error is above."
  SKIPPED+=("#622 commons:provision runs after migrate (the Cloud Run read failed; re-run)")
elif [[ -z "$commons_job" ]]; then
  warn "Cloud Run has no commons-provision job yet: #179 adds it."
  SKIPPED+=("#622 commons:provision runs after migrate, once #179 adds the job")
elif ! commons_out="$(gcloud run jobs executions list --job=commons-provision --region="$GCP_REGION" \
  --project="$PROJECT" --limit=1 --format='table(name,status.completionTime,status.succeededCount)')"; then
  warn "Couldn't list commons-provision's executions: gcloud's error is above."
  SKIPPED+=("#622 commons:provision runs after migrate (the Cloud Run read failed; re-run)")
elif [[ -z "$commons_out" ]]; then
  warn "commons-provision has no execution yet: a deploy runs it after migrate."
  SKIPPED+=("#622 commons:provision runs after migrate: quote its first execution")
else
  record_evidence "#622" "Latest commons-provision execution (that it ran after migrate in the same deploy is still to check)" \
    "gcloud run jobs executions list --job=commons-provision --region=$GCP_REGION --project=$PROJECT --limit=1" \
    "$commons_out"
fi
SKIPPED+=("#622 one deploy runs end to end on GitHub Actions, once it can start jobs again")
pause

stage "Sign in (#194)"
open_url "$APP_ORIGIN/sign-in"
step "Sign in to $APP_ORIGIN with Google, or with a link sent to your email address."
note "While SES is in the sandbox, a sign-in link reaches only an address verified with ./infra/wizards/staff-and-ses.sh."
pause "Press Enter once you are signed in to $APP_ORIGIN in the browser"

stage "Create the organisation and pilot project (#194)"
ask_valid ask ORG_SLUG "Production organisation slug:" "$SLUG_PATTERN" "Use lowercase letters, digits and hyphens."
write_env ORG_SLUG "$ORG_SLUG"
ask_valid ask PROJECT_SLUG "Production pilot project slug:" "$SLUG_PATTERN" "Use lowercase letters, digits and hyphens."
write_env PROJECT_SLUG "$PROJECT_SLUG"
say "If the organisation and project already exist in production, press Enter to verify them in the next stage."
if confirm "Open $APP_ORIGIN/new and $APP_ORIGIN/$ORG_SLUG/new to create them now?"; then
  open_url "$APP_ORIGIN/new"
  step "Create the organisation with slug '$ORG_SLUG' (if not already created)."
  open_url "$APP_ORIGIN/$ORG_SLUG/new"
  step "Create the project with slug '$PROJECT_SLUG', the Bukit Jalil site coordinates, time zone Asia/Kuala_Lumpur, and the Sky pack ticked."
  note "Creating the project with Sky ticked publishes the default Sky clause sheet (v1)."
  note "The redirect to /$ORG_SLUG/$PROJECT_SLUG/settings/packs will show an error banner until #138 is built; the project itself is saved."
  pause "Press Enter once the project is created"
fi

stage "Create a read API key and verify project & Sky sheet (#194)"
open_url "$APP_ORIGIN/$ORG_SLUG/settings/api-keys"
say "This run's checks need a read-scope API key for '$ORG_SLUG'. It stays in memory, and the last stage"
say "offers to revoke it. #194's @production specs need a key of their own when you run them."
step "If the page shows an API key form (#105), create a key named production-pilot, scope read, expiring in 1 day."
step "While the page is blank, run this in its DevTools console. Creating a key needs a sign-in"
note "  within the last 12 hours, so sign in again if it logs reauth-required:"
note "  fetch('/api/orgs/$ORG_SLUG/api-keys',{method:'POST',headers:{'content-type':'application/json','idempotency-key':crypto.randomUUID()},body:JSON.stringify({name:'production-pilot',scopes:['read'],expires_in_days:1})}).then(r=>r.json()).then(d=>console.log(d.key??d))"
note "If you still hold this wizard's key from a run in the last day, paste that one instead."
ask_valid ask_secret SKYCLAUSE_API_KEY "Paste the read API key (hidden, never saved to disk):" "$API_KEY_PATTERN" \
  "An API key starts with skc_."
KEY_HINT="$(key_prefix "$SKYCLAUSE_API_KEY")"
say "Verifying project '$PROJECT_SLUG' in '$ORG_SLUG' with key $KEY_HINT..."
api_get "/v1/projects?slug=$PROJECT_SLUG&include=summary"
if [[ "$API_STATUS" != "200" ]]; then
  warn "GET /v1/projects?slug=$PROJECT_SLUG&include=summary answered HTTP $API_STATUS: $API_BODY"
  exit 1
fi
PROJECT_ID="$(json_field "data['data'][0]['id'] if data.get('data') else ''")"
if [[ -z "$PROJECT_ID" ]]; then
  warn "No project with slug '$PROJECT_SLUG' found in organisation '$ORG_SLUG'. Create it in stage 4 and re-run."
  exit 1
fi
write_env PROJECT_ID "$PROJECT_ID"
project_summary="$API_BODY"
api_get "/v1/projects/$PROJECT_ID/clause-sheets"
if [[ "$API_STATUS" == "200" ]]; then
  record_evidence "#194" "Organisation, project and default Sky clause sheet (API key $KEY_HINT)" \
    "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects?slug=$PROJECT_SLUG&include=summary' && curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/clause-sheets'" \
    "$(printf '%s\n%s' "$project_summary" "$API_BODY")"
else
  warn "GET /v1/projects/$PROJECT_ID/clause-sheets answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#194 record the project and its default Sky clause sheet (the sheets read answered HTTP $API_STATUS)")
fi
pause

stage "Verify the ledger chain and pilot archive (#531)"
api_get "/v1/projects/$PROJECT_ID/ledger/verify"
if [[ "$API_STATUS" != "200" ]]; then
  warn "GET /v1/projects/$PROJECT_ID/ledger/verify answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#531 verify the ledger chain (HTTP $API_STATUS)")
elif [[ "$(json_field "data['valid'] is True")" == "True" ]]; then
  printf '  %s✓ verified%s /v1/projects/%s/ledger/verify answered valid=true\n' "$GREEN" "$RESET" "$PROJECT_ID"
  record_evidence "#531" "Production /ledger/verify for the pilot project" \
    "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/ledger/verify'" \
    "$API_BODY"
else
  warn "The ledger chain doesn't verify: $API_BODY"
  SKIPPED+=("#531 the pilot project's ledger chain doesn't verify: report its first_bad_entry_id to #146's owner")
fi
api_get "/v1/projects/$PROJECT_ID/pilot-archive"
if [[ "$API_STATUS" != "200" ]]; then
  warn "GET /v1/projects/$PROJECT_ID/pilot-archive answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#531 check the pilot archive (HTTP $API_STATUS)")
else
  # Each object's url is a signed download link, a credential for 15 minutes, so only these fields are kept.
  archive_objects="$(json_field "'\n'.join('kind=%s sha256=%s captured_at=%s' % (o['kind'], o['sha256'], o['captured_at']) for o in data.get('data', []))")"
  if [[ -n "$archive_objects" ]]; then
    record_evidence "#531" "Pilot archive objects (kind, sha256 and capture time; download links left out)" \
      "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/pilot-archive'" \
      "$archive_objects"
  else
    note "The pilot archive has no object yet: a person uploads the files and runs the pilot-archive job after"
    note "17 November 2026 (infra/README.md 'Pilot archive')."
    SKIPPED+=("#531 upload the pilot archive files and run the pilot-archive job, after 17 November 2026")
  fi
fi
pause

stage "Bind Bukit Jalil sources (#194)"
api_get "/v1/catalogue/sources"
if not_built b-source-binding; then
  warn "Source binding isn't built in production: GET /v1/catalogue/sources answers 501 not-built (b-source-binding, #138)."
  SKIPPED+=("#194 bind the Bukit Jalil sources, once production builds source binding (#138)")
elif [[ "$API_STATUS" == "200" ]]; then
  open_url "$APP_ORIGIN/$ORG_SLUG/$PROJECT_SLUG/settings/packs"
  step "Bind the real Bukit Jalil sources for the Sky pack and save."
  pause "Press Enter once Bukit Jalil sources are bound"
  api_get "/v1/projects?slug=$PROJECT_SLUG&include=summary"
  if [[ "$API_STATUS" == "200" ]]; then
    record_evidence "#194" "Project summary after binding the Bukit Jalil sources (its next step, not the bound sources)" \
      "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects?slug=$PROJECT_SLUG&include=summary'" \
      "$API_BODY"
  else
    warn "GET /v1/projects?slug=$PROJECT_SLUG&include=summary answered HTTP $API_STATUS: $API_BODY"
    SKIPPED+=("#194 record the project summary after binding sources (HTTP $API_STATUS)")
  fi
else
  warn "GET /v1/catalogue/sources answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#194 bind the Bukit Jalil sources (the sources read answered HTTP $API_STATUS)")
fi
pause

stage "Declare storm-afternoon windows (#194)"
api_get "/v1/projects/$PROJECT_ID/windows"
if not_built b-windows-api; then
  warn "Windows aren't built in production: GET /v1/projects/$PROJECT_ID/windows answers 501 not-built (b-windows-api, #139)."
  SKIPPED+=("#194 declare windows on forecast storm afternoons, once production builds windows (#139)")
elif [[ "$API_STATUS" == "200" ]]; then
  window_count="$(json_field "len(data.get('data', []))")"
  if (( window_count == 0 )); then
    open_url "$APP_ORIGIN/$ORG_SLUG/$PROJECT_SLUG/windows"
    step "Declare windows on forecast storm afternoons (14:00–19:15 MYT)."
    pause "Press Enter once the windows are declared"
    api_get "/v1/projects/$PROJECT_ID/windows"
  fi
  window_count=0
  [[ "$API_STATUS" == "200" ]] && window_count="$(json_field "len(data['data'])")"
  if (( window_count > 0 )); then
    record_evidence "#194" "Declared project windows" \
      "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/windows'" \
      "$API_BODY"
  else
    warn "The project still has no window: GET /v1/projects/$PROJECT_ID/windows answered HTTP $API_STATUS: $API_BODY"
    SKIPPED+=("#194 declare windows on forecast storm afternoons")
  fi
else
  warn "GET /v1/projects/$PROJECT_ID/windows answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#194 declare windows (the windows read answered HTTP $API_STATUS)")
fi
pause

stage "Put yourself on the rota (#194)"
open_url "$APP_ORIGIN/$ORG_SLUG/settings/rota"
step "Add a storm_afternoon shift (14:00–19:15 MYT) for your approver account and click Save."
if confirm "Have you saved your shift on the rota at $APP_ORIGIN/$ORG_SLUG/settings/rota?"; then
  record_evidence "#194" "Approver rota configured (your confirmation, not checked by the wizard)" \
    "open $APP_ORIGIN/$ORG_SLUG/settings/rota" \
    "Confirmed in the browser: a storm_afternoon shift (14:00–19:15 Asia/Kuala_Lumpur) is saved on organisation '$ORG_SLUG'."
else
  SKIPPED+=("#194 put yourself on the rota at $APP_ORIGIN/$ORG_SLUG/settings/rota")
fi
pause

stage "Subscribe team Gmail and Outlook addresses (#194, #536)"
subscribers_label="Confirmed subscriber counts (counts only: not which inboxes they are)"
subscribers_cmd="curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/subscriber-counts'"
api_get "/v1/projects/$PROJECT_ID/subscriber-counts"
if [[ "$API_STATUS" != "200" ]]; then
  warn "GET /v1/projects/$PROJECT_ID/subscriber-counts answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#194 subscribe and confirm one team Gmail and one team Outlook address (the counts read answered HTTP $API_STATUS)")
else
  confirmed_count="$(json_field "int(data['confirmed'])")"
  if (( confirmed_count >= 2 )); then
    printf '  %s✓ verified%s %s confirmed subscribers on project %s\n' "$GREEN" "$RESET" "$confirmed_count" "$PROJECT_SLUG"
    record_evidence "#194" "$subscribers_label" "$subscribers_cmd" "$API_BODY"
  elif confirm "Open $APP_ORIGIN/$ORG_SLUG/$PROJECT_SLUG/subscribers to subscribe and confirm the team Gmail and Outlook addresses now?"; then
    note "While SES is in the sandbox, verify both addresses first with ./infra/wizards/staff-and-ses.sh."
    open_url "$APP_ORIGIN/$ORG_SLUG/$PROJECT_SLUG/subscribers"
    step "Import one team Gmail and one team Outlook address, then click the confirmation link in each inbox."
    pause "Press Enter once both confirmation links are clicked"
    api_get "/v1/projects/$PROJECT_ID/subscriber-counts"
    confirmed_count=0
    [[ "$API_STATUS" == "200" ]] && confirmed_count="$(json_field "int(data['confirmed'])")"
    if (( confirmed_count >= 2 )); then
      record_evidence "#194" "$subscribers_label" "$subscribers_cmd" "$API_BODY"
    else
      warn "GET /v1/projects/$PROJECT_ID/subscriber-counts answered HTTP $API_STATUS, without 2 confirmed subscribers: $API_BODY"
      SKIPPED+=("#194 subscribe and confirm one team Gmail and one team Outlook address")
    fi
  else
    SKIPPED+=("#194 subscribe and confirm one team Gmail and one team Outlook address")
  fi
fi
pause

stage "Add webhook receiver and check ICS feed (#194, #534)"
api_get "/v1/webhooks"
if not_built e-webhooks; then
  warn "Signed webhooks aren't built in production: GET /v1/webhooks answers 501 not-built (e-webhooks, #193)."
  SKIPPED+=("#194 add a webhook to an HTTPS receiver you control, once production builds webhooks (#193)")
elif [[ "$API_STATUS" == "200" || "$API_STATUS" == "403" ]]; then
  if [[ "$API_STATUS" == "403" ]]; then
    note "A read key gets 403 from GET /v1/webhooks: listing webhooks needs integrations.manage, an admin-scope"
    note "statement. So the wizard can't tell whether webhooks are built; the settings page shows you."
  fi
  open_url "$APP_ORIGIN/$ORG_SLUG/settings/webhooks"
  step "Register an HTTPS receiver you control for project '$PROJECT_SLUG'."
  step "If the page can't load webhooks, open DevTools' Network tab: a 501 not-built answer from /v1/webhooks"
  note "  means they aren't built yet (#193), so answer n."
  if confirm "Is a webhook to your HTTPS receiver registered?"; then
    record_evidence "#194" "Webhook endpoint registered (your confirmation, not checked by the wizard)" \
      "open $APP_ORIGIN/$ORG_SLUG/settings/webhooks" \
      "Confirmed in the browser: an HTTPS webhook endpoint is registered for organisation '$ORG_SLUG'."
  else
    SKIPPED+=("#194 add a webhook to an HTTPS receiver you control (a 501 not-built from /v1/webhooks means it waits on #193)")
  fi
else
  warn "GET /v1/webhooks answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#194 add a webhook to an HTTPS receiver you control (the webhooks read answered HTTP $API_STATUS)")
fi

# sent_calls stays empty when the read fails, so nothing below mistakes a failure for "no call yet".
sent_calls=""
api_get "/v1/projects/$PROJECT_ID/calls?state=sent&limit=1"
if [[ "$API_STATUS" == "200" ]]; then
  sent_calls="$(json_field "len(data['data'])")"
else
  warn "GET /v1/projects/$PROJECT_ID/calls?state=sent answered HTTP $API_STATUS: $API_BODY"
  SKIPPED+=("#534, #536, #539 and #194's live checks (the calls read answered HTTP $API_STATUS; re-run)")
fi
if [[ "$sent_calls" == "0" ]]; then
  warn "#534 needs a feed with a sent call, and the project has none yet. A first real crossing needs bound"
  note "sources (#138), declared windows (#139) and the evaluator that writes crossings (#133)."
  SKIPPED+=("#534 validate the production ICS feed, once a call is sent")
elif [[ -n "$sent_calls" ]]; then
  feed_url="$MARKETING_ORIGIN/p/$ORG_SLUG/$PROJECT_SLUG/calendar.ics"
  public_get "$feed_url"
  if [[ "$API_STATUS" == "200" && "$API_BODY" == *"BEGIN:VCALENDAR"* && "$API_BODY" == *"BEGIN:VEVENT"* ]]; then
    # No strict RFC 5545 validator is in the repo or a standard tool (ical.js only parses), so this is the feed only.
    record_evidence "#534" "Production ICS feed with a sent call (not validated: needs a strict RFC 5545 validator)" \
      "curl -fsS '$feed_url'" "$API_BODY"
    SKIPPED+=("#534 run a strict RFC 5545 validator on the recorded feed and quote its output")
  else
    warn "$feed_url answered HTTP $API_STATUS without a VEVENT."
    SKIPPED+=("#534 validate the production ICS feed at $feed_url (HTTP $API_STATUS, no VEVENT)")
  fi
fi
pause

stage "Check ses_events, notices & replies, and Malay sign-off (#536, #539, #194)"
# Read-only: SES delivery events (#536's NTC-1) reach the worker only through a confirmed subscription.
say "Checking the ses_events SNS subscription on $SES_EVENTS_TOPIC_ARN (#536)..."
aws_account="$(aws sts get-caller-identity --query Account --output text)" || aws_account=""
if [[ "$aws_account" != "$AWS_ACCOUNT" ]]; then
  warn "The AWS CLI isn't signed in to account $AWS_ACCOUNT${aws_account:+ (it is in $aws_account)}, so the subscription wasn't read."
  SKIPPED+=("#536 check the ses_events subscription: sign in to AWS account $AWS_ACCOUNT and re-run")
elif ! ses_subs="$(aws sns list-subscriptions-by-topic --region "$SES_REGION" --topic-arn "$SES_EVENTS_TOPIC_ARN" \
  --query 'Subscriptions[*].[Protocol,Endpoint,SubscriptionArn]' --output text)"; then
  warn "Couldn't read the ses_events subscription: AWS's error is above."
  SKIPPED+=("#536 check the ses_events subscription (the read failed)")
elif [[ "$ses_subs" == *arn:aws:sns:* && "$ses_subs" != *PendingConfirmation* ]]; then
  printf '  %s✓ confirmed%s %s\n' "$GREEN" "$RESET" "$ses_subs"
else
  warn "The ses_events subscription isn't confirmed: ${ses_subs:-the topic has no subscription}."
  note "infra/README.md 'AWS email', 'Check the subscriptions': the worker confirms it once /ses/events is live. If it"
  note "still reads PendingConfirmation, a person with AWS access sends the confirmation again from an up-to-date"
  note "main checkout. That apply covers all of infra/aws, so read its plan first and approve it only if it replaces"
  note "this one subscription and changes nothing else:"
  note "  terraform -chdir=infra/aws init"
  note "  terraform -chdir=infra/aws apply -replace=aws_sns_topic_subscription.ses_events"
  SKIPPED+=("#536 confirm the ses_events subscription by hand (infra/README.md 'AWS email')")
fi

if [[ "$sent_calls" == "0" ]]; then
  warn "With no sent call yet, #536's real notice, #539's 'keep' reply and #194's first approval wait on a real crossing."
  SKIPPED+=("#536 a real notice reaches a confirmed subscriber with its delivery event, and the Approval to provider SLI, once a call is sent")
  SKIPPED+=("#194 approve the first real crossing and run the @production specs, once one needs review")
  SKIPPED+=("#539 reply 'keep' to a production notice, once one is sent")
elif [[ -n "$sent_calls" ]]; then
  api_get "/v1/projects/$PROJECT_ID/ledger?kind=crowd_reply"
  if [[ "$API_STATUS" != "200" ]]; then
    warn "GET /v1/projects/$PROJECT_ID/ledger?kind=crowd_reply answered HTTP $API_STATUS: $API_BODY"
    SKIPPED+=("#539 capture the crowd_reply ledger entry (HTTP $API_STATUS)")
  else
    reply_count="$(json_field "len(data['data'])")"
    if (( reply_count > 0 )); then
      record_evidence "#539" "Production crowd_reply ledger entries (that one is your 'keep' reply is your check)" \
        "curl -fsS -H 'Authorization: Bearer $KEY_HINT' -H 'Skyclause-Organization: $ORG_SLUG' '$API_ORIGIN/v1/projects/$PROJECT_ID/ledger?kind=crowd_reply'" \
        "$API_BODY"
    else
      SKIPPED+=("#539 reply 'keep' to a production notice and re-run to capture the crowd_reply ledger entry")
    fi
  fi
  SKIPPED+=("#536 quote a real notice's delivery event (NTC-1) and the production Approval to provider SLI, by hand")
  SKIPPED+=("#194 approve the first real crossing and run the @production specs, by hand")
fi

say "Malay reader check for #539 (packages/i18n/catalogue/ms/replies.json):"
ms_sha="$(shasum -a 256 packages/i18n/catalogue/ms/replies.json | awk '{print $1}')"
note "SHA-256: $ms_sha"
printf '%s\n' "$(cat packages/i18n/catalogue/ms/replies.json)"
if confirm "Has a Malay reader checked and signed off packages/i18n/catalogue/ms/replies.json for #539?"; then
  record_evidence "#539" "Malay reader sign-off on packages/i18n/catalogue/ms/replies.json (your confirmation, by its SHA-256)" \
    "shasum -a 256 packages/i18n/catalogue/ms/replies.json && cat packages/i18n/catalogue/ms/replies.json" \
    "$(printf '%s  packages/i18n/catalogue/ms/replies.json\n%s' "$ms_sha" "$(cat packages/i18n/catalogue/ms/replies.json)")"
else
  SKIPPED+=("#539 Malay reader sign-off on packages/i18n/catalogue/ms/replies.json")
fi


stage "Revoke this run's API key"
say "The key $KEY_HINT isn't needed after this run; it expires 1 day after you made it."
if confirm "Revoke every API key named production-pilot in '$ORG_SLUG' now?"; then
  open_url "$APP_ORIGIN/$ORG_SLUG/settings/api-keys"
  step "Run this in the DevTools console on that page:"
  note "  $(revoke_snippet)"
  pause "Press Enter once it has logged 'revoked' for each key"
  api_get "/v1/projects?limit=1"
  if [[ "$API_STATUS" == "401" ]]; then
    printf '  %s✓ revoked%s %s: it now answers 401\n' "$GREEN" "$RESET" "$KEY_HINT"
  else
    warn "The key $KEY_HINT still answers HTTP $API_STATUS, so it isn't revoked."
    SKIPPED+=("revoke the production-pilot API key in DevTools on $APP_ORIGIN/$ORG_SLUG/settings/api-keys: $(revoke_snippet)")
  fi
else
  SKIPPED+=("revoke the production-pilot API key in DevTools on $APP_ORIGIN/$ORG_SLUG/settings/api-keys: $(revoke_snippet)")
fi
unset SKYCLAUSE_API_KEY
finish
}

run_wizard "$@"; exit
